{%- comment -%} CarboTiras · chips del buy box (misma estructura que bb-chips de ATHLEX: 2×2 en desktop, loop en celular). {%- endcomment -%}
<style>
.ctb-tick{--ctb-accent:#0B0B0B;--ctb-ink:#0B0B0B;--ctb-line:#DCDBD6;--ctb-bg:#fff;margin:0 0 14px;max-width:440px}
.ctb-tick ul{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:0;padding:0;list-style:none}
.ctb-tick li[aria-hidden="true"]{display:none}
.ctb-tick li{display:flex;align-items:center;gap:7px;min-width:0;padding:7px 9px;border:1.5px solid var(--ctb-line);
  border-radius:10px;background:var(--ctb-bg);color:var(--ctb-ink);font-size:12px;font-weight:800;line-height:1.15;
  letter-spacing:.01em;text-transform:uppercase}
.ctb-tick svg{width:16px;height:16px;flex:none;stroke:var(--ctb-accent);fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
@media (max-width:749px){
  .ctb-tick{max-width:none;overflow:hidden;
    -webkit-mask-image:linear-gradient(90deg,transparent,#000 20px,#000 calc(100% - 20px),transparent);
    mask-image:linear-gradient(90deg,transparent,#000 20px,#000 calc(100% - 20px),transparent)}
  .ctb-tick ul{display:flex;width:max-content;animation:ctb-tick 24s linear infinite}
  .ctb-tick li{white-space:nowrap}
  .ctb-tick li[aria-hidden="true"]{display:flex}
}
@keyframes ctb-tick{to{transform:translateX(calc(-50% - 4px))}}
@media (max-width:400px){.ctb-tick li{padding:6px 8px;font-size:12px;gap:5px;letter-spacing:.01em}.ctb-tick svg{width:15px;height:15px}}
</style>
