{%- comment -%}
  Igual que ATHLEX: "Mismo precio en 3 cuotas sin interés" + "con transferencia 10% OFF".
  Como ATHLEX: lee el total del pack tildado en Kaching (8-oct); sin Kaching, sigue la variante del formulario.
{%- endcomment -%}
{%- assign v = product.selected_or_first_available_variant -%}
{%- assign transf = v.price | times: 90 | divided_by: 100 -%}
<div class="ctb-cuotas">Mismo precio en <strong>3 cuotas sin interés de:</strong> <span class="ctb-cuotas__amount" data-ctb-cuotas>{{ v.price | divided_by: 3 | money }}</span></div>
<div class="ctb-transf"><span class="ctb-transf__amount" data-ctb-transf>{{ transf | money }}</span> con transferencia <span class="ctb-transf__badge">10% OFF</span></div>
<script type="application/json" data-ctb-precios>{ {%- for x in product.variants -%}"{{ x.id }}": {{ x.price }}{%- unless forloop.last -%},{%- endunless -%}{%- endfor -%} }</script>
<style>
.ctb-cuotas{color:#00a650;font-size:13px;letter-spacing:0;line-height:1.25;margin:0}
.ctb-cuotas strong{font-weight:600}
.ctb-cuotas__amount,.ctb-transf__amount{font-size:inherit;font-weight:700;letter-spacing:.2px}
.ctb-transf{color:#00a650;font-size:14px;line-height:1.25;margin:1px 0 0}
/* precio y chip "Ahorrás" (también en la barra fija) en el mismo verde (pedido de Gero, 6-oct) */
.product-page-price .main-price,.sticky-atc__price .price-item--sale,.sticky-atc__price .price__regular .price-item{color:#00a650 !important}
.product-page-price .price__badge-sale,.sticky-atc__price .price__badge-sale{background:#00a650 !important;color:#fff !important;border-color:#00a650 !important}
.product-page-price .price__badge-sale svg,.sticky-atc__price .price__badge-sale svg{color:#fff}
/* botón de la barra fija: el CTA largo entra en una línea en celular */
gad-sticky-bar .gad-sticky__row .gad-sticky__btn{white-space:nowrap;font-size:clamp(14px,4.2vw,18px);letter-spacing:.01em}
/* la barra fija entra recién con el primer scroll (Gero, 7-oct) */
gad-sticky-bar{transition:transform .35s cubic-bezier(.22,1,.36,1),opacity .3s ease}
html:not(.ctb-scrolleo) gad-sticky-bar{transform:translateY(110%);opacity:0;pointer-events:none}
@media (prefers-reduced-motion: reduce){gad-sticky-bar{transition:opacity .3s ease}html:not(.ctb-scrolleo) gad-sticky-bar{transform:none}}
.ctb-transf__badge{display:inline-block;background:#00a650;color:#fff;font-size:12px;font-weight:700;padding:1px 6px;border-radius:4px;margin-left:4px;vertical-align:1px}
</style>
<script>
(function(){
  var marcar = function(){ if (scrollY > 10) { document.documentElement.classList.add('ctb-scrolleo'); removeEventListener('scroll', marcar); } };
  addEventListener('scroll', marcar, { passive: true }); marcar();
})();
(function(){
  // cuotas y transferencia sobre el total del pack tildado en Kaching (mismo selector verificado que ATHLEX);
  // sin Kaching, sobre la variante del formulario
  var elC = document.querySelector('[data-ctb-cuotas]'), elT = document.querySelector('[data-ctb-transf]');
  var mapa = {}; try { mapa = JSON.parse(document.querySelector('[data-ctb-precios]').textContent); } catch (e) {}
  if (!elC) return;
  function fmt(c){ return '$' + (c / 100).toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
  function dinero(txt){ if (!txt) return null; var n = parseFloat(txt.replace(/[^\d.,]/g, '').replace(/\./g, '').replace(',', '.')); return isNaN(n) ? null : Math.round(n * 100); }
  function barraKaching(){
    var c = document.querySelector('.kaching-bundles__bar input:checked');
    return c && c.closest ? c.closest('.kaching-bundles__bar') : null;
  }
  function totalKaching(){
    var bar = barraKaching();
    var pr = bar && bar.querySelector('.kaching-bundles__bar-price');
    return pr ? dinero(pr.textContent) : null;
  }
  function actualizar(){
    var cents = totalKaching();
    if (!cents) { var input = document.querySelector('form[id^="product-form-"] input[name="id"], product-form input[name="id"]'); cents = input && mapa[input.value]; }
    if (!cents) return;
    // las 3 cuotas sin interés son desde el 2º pack de Kaching (Gero, 8-oct): con 1 caja no se muestran
    var bar = barraKaching(), bars = bar ? [].slice.call(document.querySelectorAll('.kaching-bundles__bar')) : [];
    elC.closest('.ctb-cuotas').style.display = bar && bars.indexOf(bar) === 0 ? 'none' : '';
    elC.textContent = fmt(cents / 3);
    if (elT) elT.textContent = fmt(cents * 0.9);
  }
  document.addEventListener('change', function(){ setTimeout(actualizar, 120); }, true);
  document.addEventListener('click', function(e){ if (e.target.closest && e.target.closest('.kaching-bundles__bars, .kaching-bundles__bar')) setTimeout(actualizar, 150); }, true);
  var intentos = 0, t = setInterval(function(){ if (totalKaching() !== null) { actualizar(); clearInterval(t); } if (++intentos > 40) clearInterval(t); }, 250);
})();
</script>

